const listSimPlayersOnWaivers = `-- name: ListSimPlayersOnWaivers :many
SELECT DISTINCT ON (t.player_id)
    t.player_id,
    t.date AS dropped_on,
    (t.date + ($1::INT) * INTERVAL '1 day')::DATE AS clears_on
FROM sim_transactions t
WHERE t.pool_id = $2
  AND t.type = 'drop'
  AND t.date > ($3::DATE - ($1::INT) * INTERVAL '1 day')
  AND NOT EXISTS (
      SELECT 1 FROM sim_waiver_claims wc
      WHERE wc.pool_id = t.pool_id
        AND wc.player_id = t.player_id
        AND wc.status = 'won'
        AND wc.resolved_at >= t.date
  )
ORDER BY t.player_id, t.date DESC
`

